        ".fb-faq{--fb-ink:#0a0a0a;--fb-ink-soft:#2a2a2a;--fb-line:#e6e6e8;--fb-card:#fff;--fb-accent:#7c3aed;box-sizing:border-box;width:100%;max-width:820px;margin:0 auto;padding:20px 0;color:#0a0a0a;font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;-webkit-font-smoothing:antialiased;line-height:1.5}" +
        ".fb-faq *,.fb-faq *::before,.fb-faq *::after{box-sizing:border-box}" +
        ".fb-faq button{font-family:inherit}" +
