        ".fb-faq-title{font-family:'Anton','Bebas Neue',Impact,sans-serif;font-weight:400;font-size:clamp(36px,7vw,60px);line-height:0.95;letter-spacing:0.005em;margin:0 0 12px;text-align:center;text-transform:uppercase;color:#fff}" +
        ".fb-faq-title em{font-style:normal;color:#a855f7;position:relative;display:inline-block}" +
        ".fb-faq-title em::after{content:'';position:absolute;left:0;right:0;bottom:4%;height:6px;background:#a855f7;opacity:0.18;z-index:-1}" +
        ".fb-faq-subtitle{text-align:center;color:rgba(255,255,255,0.7);font-size:clamp(15px,2vw,17px);margin:0 auto 32px;max-width:520px}" +
